insert into public.exercise_library (name, muscle_group, description, instructions) values
  ('Supino reto com barra', 'Peito', 'Exercício base para peitoral maior, tríceps e deltoide anterior.', 'Deite no banco com os pés firmes no chão. Segure a barra um pouco além da largura dos ombros, desça controlando até tocar levemente o peito e empurre até estender os cotovelos sem travar.'),
  ('Supino inclinado com halteres', 'Peito', 'Enfatiza a porção clavicular do peitoral.', 'Banco a 30–45°. Desça os halteres ao lado do peito com cotovelos a ~45° do tronco e empurre unindo-os acima do peito.'),
  ('Crucifixo com halteres', 'Peito', 'Isolamento do peitoral com foco no alongamento.', 'Com leve flexão nos cotovelos, abra os braços em arco até sentir alongamento no peito e retorne pelo mesmo caminho.'),
  ('Crossover na polia', 'Peito', 'Isolamento do peitoral com tensão constante.', 'Polias altas, um passo à frente. Traga as mãos para frente e para baixo, cruzando levemente, e volte controlando.'),
  ('Flexão de braço', 'Peito', 'Exercício com peso corporal para peito, ombros e tríceps.', 'Mãos na largura dos ombros, corpo alinhado da cabeça aos pés. Desça até o peito quase tocar o chão e empurre de volta.'),
  ('Puxada frontal na polia', 'Costas', 'Trabalha latíssimo do dorso e bíceps.', 'Pegada aberta, tronco levemente inclinado para trás. Puxe a barra até a parte alta do peito levando os cotovelos para baixo e volte devagar.'),
  ('Remada curvada com barra', 'Costas', 'Desenvolve espessura das costas.', 'Quadril para trás, coluna neutra, tronco inclinado ~45°. Puxe a barra em direção ao umbigo aproximando as escápulas.'),
  ('Remada baixa na polia', 'Costas', 'Remada sentada para dorsais e romboides.', 'Sente com joelhos levemente flexionados e coluna ereta. Puxe o triângulo até o abdômen e retorne alongando sem arredondar as costas.'),
  ('Remada unilateral com halter', 'Costas', 'Trabalho unilateral das dorsais.', 'Apoie joelho e mão no banco. Puxe o halter em direção ao quadril mantendo o tronco estável.'),
  ('Barra fixa', 'Costas', 'Exercício com peso corporal para dorsais e bíceps.', 'Pegada pronada, corpo estendido. Puxe até o queixo passar a barra e desça controlando até estender os braços.'),
  ('Levantamento terra', 'Posteriores', 'Exercício composto para cadeia posterior.', 'Barra sobre o meio do pé, coluna neutra. Empurre o chão com as pernas e estenda o quadril mantendo a barra próxima ao corpo.'),
  ('Desenvolvimento com halteres', 'Ombros', 'Trabalha deltoides e tríceps.', 'Sentado, halteres na altura das orelhas. Empurre para cima sem travar os cotovelos e desça controlando.'),
  ('Elevação lateral', 'Ombros', 'Isolamento do deltoide lateral.', 'Com leve flexão nos cotovelos, eleve os halteres lateralmente até a altura dos ombros e desça devagar.'),
  ('Elevação frontal', 'Ombros', 'Isolamento do deltoide anterior.', 'Eleve o halter à frente até a altura dos ombros, sem balançar o tronco.'),
  ('Crucifixo invertido', 'Ombros', 'Trabalha deltoide posterior e parte alta das costas.', 'Tronco inclinado à frente, abra os braços lateralmente aproximando as escápulas.'),
  ('Rosca direta com barra', 'Bíceps', 'Exercício base para bíceps.', 'Cotovelos junto ao corpo. Flexione os cotovelos levando a barra até os ombros e desça controlando.'),
  ('Rosca alternada com halteres', 'Bíceps', 'Bíceps com supinação do punho.', 'Alterne os braços girando o punho para cima durante a subida.'),
  ('Rosca martelo', 'Bíceps', 'Trabalha braquial e braquiorradial.', 'Pegada neutra (palmas para dentro). Flexione os cotovelos sem mover os ombros.'),
  ('Tríceps na polia (corda)', 'Tríceps', 'Isolamento do tríceps.', 'Cotovelos fixos ao lado do corpo. Estenda os braços abrindo a corda no final e volte devagar.'),
  ('Tríceps testa', 'Tríceps', 'Isolamento do tríceps deitado.', 'Deitado, braços estendidos. Flexione apenas os cotovelos levando a barra em direção à testa e estenda de volta.'),
  ('Mergulho no banco', 'Tríceps', 'Tríceps com peso corporal.', 'Mãos no banco atrás do corpo. Desça flexionando os cotovelos até ~90° e empurre de volta.'),
  ('Agachamento livre', 'Quadríceps', 'Exercício composto para membros inferiores.', 'Pés na largura dos ombros, barra apoiada no trapézio. Desça como se fosse sentar, joelhos alinhados com os pés, e suba empurrando o chão.'),
  ('Leg press 45°', 'Quadríceps', 'Trabalha quadríceps e glúteos com apoio.', 'Pés na plataforma na largura dos ombros. Desça até ~90° de flexão de joelho sem tirar o quadril do banco e empurre.'),
  ('Cadeira extensora', 'Quadríceps', 'Isolamento do quadríceps.', 'Ajuste o apoio no tornozelo. Estenda os joelhos completamente e desça controlando.'),
  ('Afundo (passada)', 'Quadríceps', 'Exercício unilateral para pernas e glúteos.', 'Dê um passo à frente e desça até os dois joelhos formarem ~90°. Empurre com a perna da frente para voltar.'),
  ('Agachamento búlgaro', 'Quadríceps', 'Agachamento unilateral com pé de trás elevado.', 'Pé de trás apoiado no banco. Desça verticalmente mantendo o tronco estável e suba pela perna da frente.'),
  ('Mesa flexora', 'Posteriores', 'Isolamento dos isquiotibiais.', 'Deitado de bruços, flexione os joelhos trazendo o rolo em direção aos glúteos e desça devagar.'),
  ('Stiff com halteres', 'Posteriores', 'Posteriores de coxa e glúteos.', 'Joelhos levemente flexionados, leve o quadril para trás descendo os halteres rente às pernas, coluna neutra, e volte contraindo os glúteos.'),
  ('Elevação pélvica', 'Glúteos', 'Exercício principal para glúteo máximo.', 'Costas apoiadas no banco, barra sobre o quadril. Eleve o quadril até alinhar com o tronco e contraia os glúteos no topo.'),
  ('Abdução de quadril na máquina', 'Glúteos', 'Trabalha glúteo médio.', 'Sentado, abra as pernas contra a resistência e retorne controlando.'),
  ('Glúteo na polia (coice)', 'Glúteos', 'Isolamento do glúteo máximo.', 'Tornozeleira na polia baixa. Estenda o quadril levando a perna para trás sem arquear a lombar.'),
  ('Panturrilha em pé', 'Panturrilhas', 'Trabalha gastrocnêmio.', 'Ponta dos pés na plataforma. Suba o máximo possível, pause e desça alongando.'),
  ('Panturrilha sentado', 'Panturrilhas', 'Enfatiza o sóleo.', 'Sentado, joelhos a 90°. Eleve os calcanhares e desça alongando.'),
  ('Prancha', 'Abdômen', 'Estabilização do core.', 'Antebraços no chão, corpo alinhado. Mantenha o abdômen contraído sem deixar o quadril cair.'),
  ('Abdominal crunch', 'Abdômen', 'Reto abdominal.', 'Deitado, joelhos flexionados. Eleve os ombros do chão contraindo o abdômen e desça devagar.'),
  ('Elevação de pernas', 'Abdômen', 'Ênfase na porção inferior do abdômen.', 'Deitado ou suspenso, eleve as pernas estendidas sem impulso e desça controlando.'),
  ('Abdominal bicicleta', 'Abdômen', 'Reto abdominal e oblíquos.', 'Alterne cotovelo em direção ao joelho oposto em movimento de pedalada.'),
  ('Burpee', 'Corpo inteiro', 'Exercício metabólico de corpo inteiro.', 'Agache, apoie as mãos, leve os pés para trás, faça uma flexão, volte os pés e salte.'),
  ('Kettlebell swing', 'Corpo inteiro', 'Potência de quadril e condicionamento.', 'Leve o kettlebell entre as pernas com o quadril para trás e projete-o à frente estendendo o quadril com força.');
